function el(id){return els[id]||(els[id]={id,textContent:'',value:id==='speed'?'1.0':'',style:{},listeners:{},
 addEventListener(e,f){this.listeners[e]=f},setAttribute(){},getContext:()=>ctx,getBoundingClientRect:()=>({left:0,top:0})});}
