eval(src);
console.log('init:',els.playBtn.textContent,els.count.textContent,els.state.textContent);
let t=Date.now();for(let i=0;i<5;i++){const f=raf.shift();f(t+=16);}
els.playBtn.listeners.click();els.speed.value='3.0';els.speed.listeners.input();
for(let i=0;i<120;i++){const f=raf.shift();f(t+=16);}
